from collections import Counter
def f(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    line=None
    for i in range(h):
        if len(set(g[i]))==1: line=g[i][0]
    if line is None:
        for j in range(w):
            cs={g[i][j] for i in range(h)}
            if len(cs)==1: line=g[i][j]
    if line is None:
        line=[c for c,_ in cnt.most_common() if c!=bg][1] if len(cnt)>2 else None
        line=[c for c,_ in cnt.most_common() if c not in (bg,)][1]
    oddset={c for c in cnt if c not in (bg,line)}
    orows=sorted({i for i in range(h) for j in range(w) if g[i][j] in oddset})
    ocols=sorted({j for i in range(h) for j in range(w) if g[i][j] in oddset})
    rp=[(orows[i],orows[i+1]) for i in range(len(orows)-1)]
    cp=[(ocols[j],ocols[j+1]) for j in range(len(ocols)-1)]
    out=[]
    for r1,r2 in rp:
        row=[]
        for c1,c2 in cp:
            vals={g[r1][c1],g[r1][c2],g[r2][c1],g[r2][c2]}
            row.append(vals.pop() if len(vals)==1 else bg)
        out.append(row)
    return out
